-- Initial schema for Copy Trading by Salts.
-- IDs are generated by Prisma Client (cuid); do not insert rows with empty IDs.

CREATE TYPE "UserStatus" AS ENUM ('INVITED', 'ACTIVE', 'SUSPENDED', 'DELETED');
CREATE TYPE "UserRole" AS ENUM ('SUBSCRIBER', 'HOST', 'ADMIN');
CREATE TYPE "Market" AS ENUM ('INDIA', 'CRYPTO');
CREATE TYPE "ConnectionStatus" AS ENUM ('PENDING', 'CONNECTED', 'ERROR', 'DISCONNECTED', 'REAUTH_REQUIRED');
CREATE TYPE "TradingMode" AS ENUM ('PAPER', 'LIVE');
CREATE TYPE "ListingStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'PAUSED', 'REMOVED', 'SUSPENDED');
CREATE TYPE "SubscriptionStatus" AS ENUM ('ACTIVE', 'PAUSED', 'UNSUBSCRIBED');
CREATE TYPE "CopyOrderStatus" AS ENUM ('QUEUED', 'SKIPPED', 'SUBMITTED', 'ACKNOWLEDGED', 'PARTIALLY_FILLED', 'FILLED', 'CANCELLED', 'REJECTED', 'UNKNOWN');
CREATE TYPE "SignalEventType" AS ENUM ('ENTRY', 'EXIT', 'PARTIAL_EXIT', 'MODIFY_ORDER', 'CANCEL', 'PLACE_STOP_LOSS', 'MODIFY_STOP_LOSS', 'CANCEL_STOP_LOSS', 'PLACE_TAKE_PROFIT', 'MODIFY_TAKE_PROFIT', 'CANCEL_TAKE_PROFIT', 'TRAIL_STOP', 'SQUARE_OFF');

CREATE TABLE "User" (
  "id" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "passwordHash" TEXT NOT NULL,
  "displayName" TEXT NOT NULL,
  "status" "UserStatus" NOT NULL DEFAULT 'INVITED',
  "roles" "UserRole"[] NOT NULL DEFAULT ARRAY['SUBSCRIBER']::"UserRole"[],
  "totpEnabled" BOOLEAN NOT NULL DEFAULT false,
  "totpSecretEncrypted" BYTEA,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "User_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");

CREATE TABLE "Invite" (
  "id" TEXT NOT NULL,
  "tokenHash" TEXT NOT NULL,
  "createdById" TEXT NOT NULL,
  "expiresAt" TIMESTAMP(3) NOT NULL,
  "usedAt" TIMESTAMP(3),
  "usedById" TEXT,
  "revokedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Invite_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "Invite_tokenHash_key" ON "Invite"("tokenHash");
CREATE INDEX "Invite_createdById_idx" ON "Invite"("createdById");
ALTER TABLE "Invite" ADD CONSTRAINT "Invite_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "DisclosureVersion" (
  "id" TEXT NOT NULL,
  "market" "Market",
  "version" TEXT NOT NULL,
  "contentHash" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "DisclosureVersion_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "DisclosureVersion_market_version_key" ON "DisclosureVersion"("market", "version");

CREATE TABLE "DisclosureAcceptance" (
  "id" TEXT NOT NULL,
  "userId" TEXT NOT NULL,
  "versionId" TEXT NOT NULL,
  "acceptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "ipAddress" TEXT NOT NULL,
  "userAgent" TEXT NOT NULL,
  CONSTRAINT "DisclosureAcceptance_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "DisclosureAcceptance_userId_versionId_key" ON "DisclosureAcceptance"("userId", "versionId");
CREATE INDEX "DisclosureAcceptance_versionId_idx" ON "DisclosureAcceptance"("versionId");
ALTER TABLE "DisclosureAcceptance" ADD CONSTRAINT "DisclosureAcceptance_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "DisclosureAcceptance" ADD CONSTRAINT "DisclosureAcceptance_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "DisclosureVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "BrokerConnection" (
  "id" TEXT NOT NULL,
  "userId" TEXT NOT NULL,
  "market" "Market" NOT NULL,
  "provider" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "encryptedSecret" BYTEA NOT NULL,
  "keyFingerprint" TEXT NOT NULL,
  "permissions" JSONB NOT NULL,
  "status" "ConnectionStatus" NOT NULL DEFAULT 'PENDING',
  "lastHealthAt" TIMESTAMP(3),
  "tokenExpiresAt" TIMESTAMP(3),
  "egressProfileId" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "BrokerConnection_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "BrokerConnection_userId_market_idx" ON "BrokerConnection"("userId", "market");
ALTER TABLE "BrokerConnection" ADD CONSTRAINT "BrokerConnection_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "HostListing" (
  "id" TEXT NOT NULL,
  "hostUserId" TEXT NOT NULL,
  "market" "Market" NOT NULL,
  "title" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "riskDisclosure" TEXT NOT NULL,
  "status" "ListingStatus" NOT NULL DEFAULT 'DRAFT',
  "publishedAt" TIMESTAMP(3),
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "HostListing_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "HostListing_market_status_idx" ON "HostListing"("market", "status");
CREATE INDEX "HostListing_hostUserId_idx" ON "HostListing"("hostUserId");
ALTER TABLE "HostListing" ADD CONSTRAINT "HostListing_hostUserId_fkey" FOREIGN KEY ("hostUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "HostSubscription" (
  "id" TEXT NOT NULL,
  "hostUserId" TEXT NOT NULL,
  "subscriberId" TEXT NOT NULL,
  "listingId" TEXT NOT NULL,
  "market" "Market" NOT NULL,
  "status" "SubscriptionStatus" NOT NULL DEFAULT 'ACTIVE',
  "mode" "TradingMode" NOT NULL DEFAULT 'PAPER',
  "settings" JSONB NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "HostSubscription_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "HostSubscription_subscriberId_listingId_key" ON "HostSubscription"("subscriberId", "listingId");
CREATE INDEX "HostSubscription_subscriberId_market_status_idx" ON "HostSubscription"("subscriberId", "market", "status");
CREATE INDEX "HostSubscription_hostUserId_idx" ON "HostSubscription"("hostUserId");
CREATE INDEX "HostSubscription_listingId_idx" ON "HostSubscription"("listingId");
ALTER TABLE "HostSubscription" ADD CONSTRAINT "HostSubscription_hostUserId_fkey" FOREIGN KEY ("hostUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "HostSubscription" ADD CONSTRAINT "HostSubscription_subscriberId_fkey" FOREIGN KEY ("subscriberId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "HostSubscription" ADD CONSTRAINT "HostSubscription_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "HostListing"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "Signal" (
  "id" TEXT NOT NULL,
  "idempotencyKey" TEXT NOT NULL,
  "hostUserId" TEXT NOT NULL,
  "hostConnectionId" TEXT NOT NULL,
  "market" "Market" NOT NULL,
  "event" "SignalEventType" NOT NULL,
  "instrument" JSONB NOT NULL,
  "payload" JSONB NOT NULL,
  "occurredAt" TIMESTAMP(3) NOT NULL,
  "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Signal_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "Signal_idempotencyKey_key" ON "Signal"("idempotencyKey");
CREATE INDEX "Signal_hostUserId_market_occurredAt_idx" ON "Signal"("hostUserId", "market", "occurredAt");

CREATE TABLE "CopyOrder" (
  "id" TEXT NOT NULL,
  "signalId" TEXT NOT NULL,
  "subscriberId" TEXT NOT NULL,
  "connectionId" TEXT NOT NULL,
  "clientOrderId" TEXT NOT NULL,
  "brokerOrderId" TEXT,
  "status" "CopyOrderStatus" NOT NULL DEFAULT 'QUEUED',
  "requestedQty" DECIMAL(28,10) NOT NULL,
  "filledQty" DECIMAL(28,10) NOT NULL DEFAULT 0,
  "averageFill" DECIMAL(28,10),
  "failureCode" TEXT,
  "failureMessage" TEXT,
  "latencyMs" INTEGER,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "CopyOrder_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "CopyOrder_clientOrderId_key" ON "CopyOrder"("clientOrderId");
CREATE UNIQUE INDEX "CopyOrder_signalId_subscriberId_connectionId_key" ON "CopyOrder"("signalId", "subscriberId", "connectionId");
CREATE INDEX "CopyOrder_subscriberId_status_createdAt_idx" ON "CopyOrder"("subscriberId", "status", "createdAt");
CREATE INDEX "CopyOrder_connectionId_idx" ON "CopyOrder"("connectionId");
ALTER TABLE "CopyOrder" ADD CONSTRAINT "CopyOrder_signalId_fkey" FOREIGN KEY ("signalId") REFERENCES "Signal"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "AuditEvent" (
  "id" TEXT NOT NULL,
  "actorId" TEXT,
  "tenantId" TEXT,
  "action" TEXT NOT NULL,
  "targetType" TEXT NOT NULL,
  "targetId" TEXT NOT NULL,
  "requestId" TEXT NOT NULL,
  "metadata" JSONB,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "AuditEvent_tenantId_createdAt_idx" ON "AuditEvent"("tenantId", "createdAt");
CREATE INDEX "AuditEvent_actorId_idx" ON "AuditEvent"("actorId");
ALTER TABLE "AuditEvent" ADD CONSTRAINT "AuditEvent_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

CREATE TABLE "Session" (
  "id" TEXT NOT NULL,
  "userId" TEXT NOT NULL,
  "tokenHash" TEXT NOT NULL,
  "expiresAt" TIMESTAMP(3) NOT NULL,
  "revokedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "mfaVerifiedAt" TIMESTAMP(3),
  CONSTRAINT "Session_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash");
CREATE INDEX "Session_userId_expiresAt_idx" ON "Session"("userId", "expiresAt");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
